<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { stats } from '../../stores/stats.svelte.ts';
  import { getPassiveGrowthRows } from '../../lib/statsVisualData.js';
  import { formatNumber } from '../../../formatters.ts';

  function formatGrowthRate(value: unknown): string {
    const n = Number(value);
    if (!Number.isFinite(n) || n <= 0) return '0';
    if (n < 1) return n.toFixed(3);
    if (n < 10) return n.toFixed(2);
    if (n < 100) return n.toFixed(1);
    return formatNumber(n);
  }

  let gm = $derived(game as GameRuntime | null);
  let t = $derived((key: string) => gm?.t?.(`statsUi.${key}`) ?? key);

  let rows = $derived.by(() => {
    stats.contentRevision;
    if (!gm) return [];
    return getPassiveGrowthRows(gm);
  });
</script>

<div class="farming-metrics-section">
  <div class="farming-metrics-section-title">{t('sectionGrowthAnalysis')}</div>
  <div class="farming-metrics-grid">
    {#if rows.length === 0}
      <div class="metric-row metric-row-wide">
        <span class="metric-label">{t('growthEmpty')}</span>
      </div>
    {:else}
      {#each rows as row (row.key)}
        <div class="metric-row metric-row-wide" class:metric-row-highlight={row.key === 'hp'}>
          <span class="metric-label">{row.label}</span>
          <span class="metric-value">
            {row.doublingText}<span class="metric-value-extra">{t('growthDoubling')}</span>
          </span>
          <div class="metric-sub">
            {t('growthCurrent')}: {formatNumber(row.current)} • {t('growthGainPerSec')}: +{formatGrowthRate(row.gainPerSecond)}
          </div>
          <div class="metric-sub">
            {t('growthGainPerHour')}: +{formatNumber(row.gainPerHour)} ({row.hourlyPercent.toFixed(2)}%)
          </div>
          <div class="metric-sub">
            {t('growthInOneHour')}: {formatNumber(row.projected1h)} • {t('growthIn24Hours')}: {formatNumber(row.projected24h)}
          </div>
        </div>
      {/each}
      <div class="metric-row metric-row-wide" style="background:transparent;border:none;padding:0;margin-top:4px">
        <div class="metric-sub" style="width:100%">{t('growthAssumption')}</div>
      </div>
    {/if}
  </div>
</div>
