<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { stats } from '../../stores/stats.svelte.ts';
  import { buildTowerTabData } from '../../stats/statsTabData.js';
  import StatsMetricRows from './StatsMetricRows.svelte';

  let data = $derived.by(() => {
    stats.contentRevision;
    const gm = game as GameRuntime | null;
    if (!gm) return null;
    return buildTowerTabData(gm);
  });

  let sectionTitle = $derived((game as GameRuntime | null)?.t?.('statsUi.sectionTower') ?? 'Tour');
</script>

{#if data}
  {#if data.sessionBanner}
    <StatsMetricRows title="" rows={[data.sessionBanner]} first />
  {/if}
  <StatsMetricRows title={sectionTitle} rows={data.metrics} first={!data.sessionBanner} />
{/if}
