<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { stats } from '../../stores/stats.svelte.ts';
  import { buildQuestsTabData } from '../../stats/statsTabData.js';
  import StatsMetricRows from './StatsMetricRows.svelte';
  import StatsRankedList from './StatsRankedList.svelte';

  let data = $derived.by(() => {
    stats.contentRevision;
    const gm = game as GameRuntime | null;
    if (!gm) return null;
    return buildQuestsTabData(gm);
  });

  let t = $derived((key: string) => (game as GameRuntime | null)?.t?.(`statsUi.${key}`) ?? key);
</script>

{#if data}
  {#if data.sessionBanner}
    <StatsMetricRows title="" rows={[data.sessionBanner]} first />
  {/if}
  <StatsMetricRows title={t('sectionQuests')} rows={data.metrics} first={!data.sessionBanner} />
  <StatsRankedList
    title={t('sectionNearAchievements')}
    rows={data.nearAchievements}
    emptyLabel={data.nearAchievementsEmpty ? t('nearAchievementsEmpty') : ''}
  />
{/if}
