<script lang="ts">
  import { facade } from '../bus/gameFacade.ts';
  import { GameEventType as Evt } from '../bus/events.ts';
  import { useFacadeSubscription } from '../lib/useFacadeSubscription.ts';
  import { publishStatsChanged } from '../bus/publishHooks.js';
  import { stats } from '../stores/stats.svelte.ts';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import StatsCombatTab from './stats/StatsCombatTab.svelte';
  import StatsCreaturesTab from './stats/StatsCreaturesTab.svelte';
  import StatsEconomyTab from './stats/StatsEconomyTab.svelte';
  import StatsRecordsTab from './stats/StatsRecordsTab.svelte';
  import StatsTowerTab from './stats/StatsTowerTab.svelte';
  import StatsQuestsTab from './stats/StatsQuestsTab.svelte';
  import StatsGrowthTab from './stats/StatsGrowthTab.svelte';

  let { open = $bindable(false) }: { open?: boolean } = $props();

  const TAB_IDS = [
    'combat',
    'creatures',
    'economy',
    'records',
    'tower',
    'quests',
    'growth',
  ] as const;

  const TAB_I18N_KEYS: Record<(typeof TAB_IDS)[number], string> = {
    combat: 'tabCombat',
    creatures: 'tabCreatures',
    economy: 'tabEconomy',
    records: 'tabRecords',
    tower: 'tabTower',
    quests: 'tabQuests',
    growth: 'tabGrowth',
  };

  let activeTab = $state('combat');
  let displayEl = $state<HTMLDivElement | null>(null);
  let rootEl = $state<HTMLDivElement | null>(null);
  let previousFocus = $state<Element | null>(null);
  let lastLiveRefreshAt = 0;
  const LIVE_REFRESH_MS = 1500;

  let tabs = $derived.by(() => {
    stats.contentRevision;
    const gm = game as GameRuntime | null;
    return TAB_IDS.map((id) => ({
      id,
      label: gm?.t?.(`statsUi.${TAB_I18N_KEYS[id]}`) ?? id,
    }));
  });

  let modalTitle = $derived.by(() => {
    stats.contentRevision;
    return (game as GameRuntime | null)?.t?.('modal.statsTitle') ?? 'Statistiques';
  });

  function close() {
    open = false;
    const gm = game as GameRuntime | null;
    if (gm && typeof gm.closeStatsModal === 'function') {
      gm.closeStatsModal();
    } else {
      facade.dispatch({ type: 'CLOSE_MODAL', modalId: 'statsModal' });
    }
    const restoreFocus = previousFocus;
    previousFocus = null;
    if (
      restoreFocus &&
      typeof (restoreFocus as HTMLElement).focus === 'function' &&
      document.contains(restoreFocus)
    ) {
      requestAnimationFrame(() => (restoreFocus as HTMLElement).focus());
    }
  }

  function selectTab(tab: string) {
    activeTab = tab;
    const gm = game as GameRuntime | null;
    if (gm && typeof gm.setStatsUi === 'function') {
      gm.setStatsUi('tab', tab);
    }
  }

  function bindStatsTooltips(container: HTMLElement) {
    const gm = game as GameRuntime | null;
    if (!gm || typeof gm.scheduleTooltip !== 'function') return;
    container.querySelectorAll('[data-tooltip-title]').forEach((row) => {
      const title = row.getAttribute('data-tooltip-title') || '';
      const desc = row.getAttribute('data-tooltip-desc') || '';
      row.addEventListener('mouseenter', (ev) => gm.scheduleTooltip(ev, title, desc));
      row.addEventListener('mouseleave', () => gm.hideTooltip?.());
    });
  }

  function refreshStatsIfOpen() {
    if (!open) return;
    const now = Date.now();
    if (now - lastLiveRefreshAt < LIVE_REFRESH_MS) return;
    lastLiveRefreshAt = now;
    publishStatsChanged(activeTab, { force: true });
  }

  function handleKeydown(e: KeyboardEvent) {
    if (e.key === 'Escape') {
      e.stopPropagation();
      close();
      return;
    }
    if (e.key === 'Tab' && rootEl) {
      const focusable = Array.from(rootEl.querySelectorAll(
        'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'
      )).filter(el => (el as HTMLElement).offsetParent !== null);
      if (focusable.length === 0) { e.preventDefault(); return; }
      const first = focusable[0] as HTMLElement;
      const last = focusable[focusable.length - 1] as HTMLElement;
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
  }

  useFacadeSubscription([Evt.MODAL_OPENED, Evt.MODAL_CLOSED, Evt.STATS_CHANGED], (evt) => {
    if (evt.type === Evt.MODAL_OPENED && evt.modalId === 'statsModal') {
      previousFocus = document.activeElement;
      open = true;
      publishStatsChanged(activeTab);
    }
    if (evt.type === Evt.MODAL_CLOSED && evt.modalId === 'statsModal') {
      open = false;
    }
    if (evt.type === Evt.STATS_CHANGED && 'tab' in evt) {
      activeTab = evt.tab;
    }
  });

  useFacadeSubscription(
    [Evt.RESOURCES_CHANGED, Evt.COMBAT_STATE_CHANGED, Evt.QUESTS_CHANGED, Evt.TEAM_CHANGED],
    () => refreshStatsIfOpen(),
  );

  $effect(() => {
    if (open) {
      document.addEventListener('keydown', handleKeydown);
      return () => document.removeEventListener('keydown', handleKeydown);
    }
  });

  $effect(() => {
    if (open) publishStatsChanged(activeTab);
  });

  $effect(() => {
    stats.contentRevision;
    const el = displayEl;
    if (!open || !el) return;
    requestAnimationFrame(() => bindStatsTooltips(el));
  });

  $effect(() => {
    if (open && rootEl) {
      requestAnimationFrame(() => {
        const first = rootEl.querySelector('.dps-meter-tab') as HTMLElement | null;
        if (first) first.focus();
      });
    }
  });

  $effect(() => {
    const target = document.getElementById('statsModal');
    const visible = open;
    if (target) {
      if (visible) {
        target.classList.add('show');
        target.setAttribute('aria-hidden', 'false');
      } else {
        target.classList.remove('show');
        target.setAttribute('aria-hidden', 'true');
      }
    }
  });
</script>

<div
  bind:this={rootEl}
  class="stats-content js-modal-content farming-metrics-modal-content stats-modal-shell"
  data-action="stopPropagation"
  data-action-stop
>
  <div class="stats-header">
    <h2 id="statsModalTitleLabel">{modalTitle}</h2>
    <button class="stats-close" onclick={close}>&#10005;</button>
  </div>
  <div class="farming-metrics-body">
    <div class="dps-meter-tabs stats-modal-tabs" role="tablist">
      {#each tabs as tab (tab.id)}
        <button
          type="button"
          class="dps-meter-tab"
          class:active={activeTab === tab.id}
          role="tab"
          aria-selected={activeTab === tab.id}
          onclick={() => selectTab(tab.id)}
          data-stats-tab={tab.id}
        >
          <span data-stats-tab-label={tab.id}>{tab.label}</span>
        </button>
      {/each}
    </div>
    <div id="statsDisplay" class="stats-modal-tab-panel" bind:this={displayEl}>
      {#if activeTab === 'combat'}
        <StatsCombatTab />
      {:else if activeTab === 'creatures'}
        <StatsCreaturesTab />
      {:else if activeTab === 'economy'}
        <StatsEconomyTab />
      {:else if activeTab === 'records'}
        <StatsRecordsTab />
      {:else if activeTab === 'tower'}
        <StatsTowerTab />
      {:else if activeTab === 'quests'}
        <StatsQuestsTab />
      {:else if activeTab === 'growth'}
        <StatsGrowthTab />
      {/if}
    </div>
  </div>
</div>
