<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { stats } from '../../stores/stats.svelte.ts';
  import { buildCreaturesTabData } from '../../stats/statsTabData.js';
  import StatsMetricRows from './StatsMetricRows.svelte';
  import StatsRankedList from './StatsRankedList.svelte';

  let data = $derived.by(() => {
    stats.contentRevision;
    const gm = game as GameRuntime | null;
    if (!gm) return null;
    return buildCreaturesTabData(gm);
  });

  let t = $derived((key: string) => (game as GameRuntime | null)?.t?.(`statsUi.${key}`) ?? key);
</script>

{#if data}
  {#if data.sessionBanner}
    <StatsMetricRows title="" rows={[data.sessionBanner]} first />
  {/if}
  <StatsMetricRows title={t('sectionCreatures')} rows={data.creaturesMetrics} first={!data.sessionBanner} />
  <StatsMetricRows title={t('sectionCreaturesExtra')} rows={data.extraMetrics} />
  <StatsMetricRows title={t('sectionPokedex')} rows={data.pokedexMetrics} />
  <StatsMetricRows title={t('sectionAvgIv')} rows={data.ivMetrics} />
  <StatsRankedList
    title={t('sectionTopContributors')}
    rows={data.topContributors}
    emptyLabel={data.topContributorsEmpty ? t('topContributorsEmpty') : ''}
  />
{/if}
