/**
 * Pure data builders for stats modal visuals (radar, heatmap, sparklines, biggest hit).
 */

import { formatNumber } from '../../formatters.ts';
import type { GameRuntime } from '../types/game.js';
import type { CreatureData } from '../types/creature.js';
import type { PassiveGrowthRow } from '../types/game/state.js';

export type StatsRadarMode = 'team' | 'pension' | 'team_pension' | 'main';

export interface StatsRadarAxis {
  key: string;
  label: string;
  valuePct: number;
  tooltip: string;
}

export interface StatsRadarData {
  mode: StatsRadarMode;
  axes: StatsRadarAxis[];
  hintKey: string;
}

export interface StatsHeatmapCell {
  key: string;
  score: number;
  intensity: number;
  isToday: boolean;
}

export interface StatsTimelineItem {
  key: string;
  label: string;
  values: number[];
  color: string;
  total: number;
}

export type StatsTimelineSource = 'farming' | 'daily' | 'none';

export interface StatsTimelineData {
  source: StatsTimelineSource;
  items: StatsTimelineItem[];
  emptyHintKey: string;
}

export interface StatsBiggestHitData {
  value: number;
  subtitle: string;
  isShiny: boolean;
}

const RADAR_MODES: StatsRadarMode[] = ['team', 'pension', 'team_pension', 'main'];

const HINT_BY_MODE: Record<StatsRadarMode, string> = {
  team: 'radarStatHintTeam',
  pension: 'radarStatHintPension',
  team_pension: 'radarStatHintTeamPension',
  main: 'radarStatHintMain',
};

function sumCreatureStats(creatures: CreatureData[]) {
  const out = { hp: 0, attack: 0, spattack: 0, defense: 0, spdefense: 0, speed: 0 };
  (creatures || []).forEach((c) => {
    if (!c) return;
    out.hp += Number(c.maxHp) || 0;
    out.attack += Number(c.attack) || 0;
    out.spattack += Number(c.spattack) || 0;
    out.defense += Number(c.defense) || 0;
    out.spdefense += Number(c.spdefense) || 0;
    out.speed += Number(c.speed) || 0;
  });
  return out;
}

export function buildStatsRadarData(
  game: GameRuntime,
  statsT: (key: string, vars?: Record<string, unknown>) => string,
): StatsRadarData | null {
  const rawMode = game.statsUi?.radarMode ?? 'team';
  const mode: StatsRadarMode = RADAR_MODES.includes(rawMode as StatsRadarMode)
    ? (rawMode as StatsRadarMode)
    : 'team';

  let stats: Record<string, number>;
  if (mode === 'main') {
    stats = game.playerMainStats || {};
  } else if (mode === 'pension') {
    stats = sumCreatureStats(game.pension);
  } else if (mode === 'team_pension') {
    const t = sumCreatureStats(game.playerTeam);
    const p = sumCreatureStats(game.pension);
    stats = {
      hp: t.hp + p.hp,
      attack: t.attack + p.attack,
      spattack: t.spattack + p.spattack,
      defense: t.defense + p.defense,
      spdefense: t.spdefense + p.spdefense,
      speed: t.speed + p.speed,
    };
  } else {
    stats = sumCreatureStats(game.playerTeam);
  }

  const HP_VISUAL_WEIGHT = 0.25;
  const axisDefs = [
    { key: 'hp', label: statsT('radarStatHp'), raw: Number(stats.hp) || 0, weight: HP_VISUAL_WEIGHT },
    { key: 'attack', label: statsT('radarStatAttack'), raw: Number(stats.attack) || 0, weight: 1 },
    { key: 'spattack', label: statsT('radarStatSpAttack'), raw: Number(stats.spattack) || 0, weight: 1 },
    { key: 'defense', label: statsT('radarStatDefense'), raw: Number(stats.defense) || 0, weight: 1 },
    { key: 'spdefense', label: statsT('radarStatSpDefense'), raw: Number(stats.spdefense) || 0, weight: 1 },
    { key: 'speed', label: statsT('radarStatSpeed'), raw: Number(stats.speed) || 0, weight: 1 },
  ];
  if (axisDefs.every((a) => a.raw <= 0)) return null;

  const weighted = axisDefs.map((a) => a.raw * a.weight);
  const avgWeighted = weighted.reduce((acc, v) => acc + v, 0) / axisDefs.length;
  if (avgWeighted <= 0) return null;

  const axes: StatsRadarAxis[] = axisDefs.map((a, idx) => {
    const w = weighted[idx] ?? 0;
    const ratio = w / avgWeighted;
    const valuePct = Math.max(0, Math.min(100, ratio * 50));
    const deltaPct = (ratio - 1) * 100;
    const deltaStr = `${deltaPct >= 0 ? '+' : ''}${deltaPct.toFixed(0)}%`;
    const baseTip = a.key === 'hp'
      ? statsT('radarStatHpTip', { value: formatNumber(a.raw) })
      : `${a.label}: ${formatNumber(a.raw)}`;
    return {
      key: a.key,
      label: a.label,
      valuePct,
      tooltip: `${baseTip} (${deltaStr} ${statsT('radarStatVsAvg')})`,
    };
  });

  return { mode, axes, hintKey: HINT_BY_MODE[mode] };
}

export function buildHeatmapCells(game: GameRuntime, weeks = 12): StatsHeatmapCell[] {
  const today = new Date();
  const totalDays = weeks * 7;
  const activity = game.statsActivityByDay || {};
  const max = Math.max(
    1,
    ...Object.values(activity).map((v) => {
      const day = v as Record<string, number>;
      return (day.combats || 0) + (day.captures || 0);
    }),
  );

  const cells: StatsHeatmapCell[] = [];
  for (let i = totalDays - 1; i >= 0; i--) {
    const d = new Date(today.getTime() - i * 86400000);
    const key = game._currentDayKey?.(d) ?? '';
    const data = key && activity[key] ? (activity[key] as Record<string, number>) : null;
    const score = data ? (Number(data.combats) || 0) + (Number(data.captures) || 0) : 0;
    const intensity = score > 0 ? Math.min(1, score / max) : 0;
    cells.push({ key, score, intensity, isToday: i === 0 });
  }
  return cells;
}

export function heatmapCellFill(intensity: number): string {
  if (intensity <= 0) return 'rgba(148,163,184,0.12)';
  if (intensity < 0.25) return 'rgba(96,165,250,0.35)';
  if (intensity < 0.5) return 'rgba(96,165,250,0.55)';
  if (intensity < 0.75) return 'rgba(96,165,250,0.75)';
  return 'rgba(96,165,250,1)';
}

export function buildSparklinePoints(values: number[], w = 220, h = 32, pad = 2): string {
  if (!Array.isArray(values) || values.length < 2) return '';
  const max = Math.max(...values, 1);
  const stepX = (w - 2 * pad) / (values.length - 1);
  return values
    .map((v, i) => {
      const x = pad + i * stepX;
      const y = h - pad - ((Number(v) || 0) / max) * (h - 2 * pad);
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(' ');
}

function farmingTimelineSeries(game: GameRuntime) {
  if (!game.farmingMetrics?.timeline) return null;
  const tl = game.farmingMetrics.timeline;
  const keys = Object.keys(tl).map(Number).filter(Number.isFinite).sort((a, b) => a - b);
  if (keys.length < 2) return null;
  const tlMap = tl as Record<number, Record<string, number>>;
  return {
    keys,
    money: keys.map((k) => tlMap[k]?.money || 0),
    xp: keys.map((k) => tlMap[k]?.xp || 0),
    captures: keys.map((k) => tlMap[k]?.captures || 0),
    combats: keys.map((k) => tlMap[k]?.combats || 0),
  };
}

function dailyActivityTimelineSeries(game: GameRuntime, days = 14) {
  const activity = game.statsActivityByDay || {};
  const keys: string[] = [];
  const combats: number[] = [];
  const captures: number[] = [];
  const today = new Date();
  for (let i = days - 1; i >= 0; i--) {
    const d = new Date(today.getTime() - i * 86400000);
    const key = game._currentDayKey?.(d) ?? '';
    keys.push(key);
    const row = key && activity[key] ? (activity[key] as Record<string, number>) : null;
    combats.push(row ? Number(row.combats) || 0 : 0);
    captures.push(row ? Number(row.captures) || 0 : 0);
  }
  const hasData = combats.some((v) => v > 0) || captures.some((v) => v > 0);
  if (!hasData || keys.length < 2) return null;
  return { keys, combats, captures };
}

export function buildStatsTimelineData(
  game: GameRuntime,
  statsT: (key: string) => string,
): StatsTimelineData {
  const colors: Record<string, string> = {
    money: '#fbbf24',
    xp: '#60a5fa',
    captures: '#a78bfa',
    combats: '#34d399',
  };

  const farming = farmingTimelineSeries(game);
  if (farming) {
    const items: StatsTimelineItem[] = [
      { key: 'money', label: statsT('timelineMoney'), values: farming.money, color: colors.money!, total: farming.money.reduce((a, b) => a + b, 0) },
      { key: 'xp', label: statsT('timelineXp'), values: farming.xp, color: colors.xp!, total: farming.xp.reduce((a, b) => a + b, 0) },
      { key: 'captures', label: statsT('timelineCaptures'), values: farming.captures, color: colors.captures!, total: farming.captures.reduce((a, b) => a + b, 0) },
      { key: 'combats', label: statsT('timelineCombats'), values: farming.combats, color: colors.combats!, total: farming.combats.reduce((a, b) => a + b, 0) },
    ];
    return { source: 'farming', items, emptyHintKey: 'timelineEmpty' };
  }

  const daily = dailyActivityTimelineSeries(game);
  if (daily) {
    const items: StatsTimelineItem[] = [
      { key: 'combats', label: statsT('timelineCombats'), values: daily.combats, color: colors.combats!, total: daily.combats.reduce((a, b) => a + b, 0) },
      { key: 'captures', label: statsT('timelineCaptures'), values: daily.captures, color: colors.captures!, total: daily.captures.reduce((a, b) => a + b, 0) },
    ];
    return { source: 'daily', items, emptyHintKey: 'timelineDailyHint' };
  }

  return { source: 'none', items: [], emptyHintKey: 'timelineEmptyHint' };
}

export function buildBiggestHitData(
  game: GameRuntime,
  statsT: (key: string) => string,
): StatsBiggestHitData | null {
  const stats = game.stats || {};
  const value = Number(stats.biggestSingleHit) || 0;
  if (value <= 0) return null;

  const owner = String(stats.biggestSingleHitOwner || '');
  const source = String(stats.biggestSingleHitSource || '');
  const sourceType = String(stats.biggestSingleHitSourceType || '');
  const isCrit = !!stats.biggestSingleHitCrit;
  const isOffline = !!stats.biggestSingleHitOffline;
  const isShiny = !!stats.biggestSingleHitOwnerShiny;

  const sourceLabel = (() => {
    if (!source) return '';
    if (sourceType === 'status') {
      const i18nKey = `status.${source}.name`;
      const localized = game.t(i18nKey);
      return localized && localized !== i18nKey ? localized : source;
    }
    return game.getLocalizedMoveName?.(source) || source;
  })();

  const subtitleParts: string[] = [];
  if (owner) subtitleParts.push((isShiny ? '✨ ' : '') + owner);
  if (sourceLabel) subtitleParts.push(sourceLabel);
  if (isCrit) subtitleParts.push(statsT('biggestHitCrit'));
  if (isOffline) subtitleParts.push(statsT('biggestHitOffline'));

  return { value, subtitle: subtitleParts.join(' • '), isShiny };
}

export function bonusRadarGeometry(axes: StatsRadarAxis[], cap = 100) {
  const n = axes.length;
  const cx = 110;
  const cy = 110;
  const R = 90;
  const angleStep = (Math.PI * 2) / n;
  const rings = [0.25, 0.5, 0.75, 1].map((r) => {
    const points = Array.from({ length: n }, (_, i) => {
      const a = -Math.PI / 2 + i * angleStep;
      return { x: cx + Math.cos(a) * R * r, y: cy + Math.sin(a) * R * r };
    });
    return points;
  });
  const axisLines = axes.map((axis, i) => {
    const a = -Math.PI / 2 + i * angleStep;
    return {
      x2: cx + Math.cos(a) * R,
      y2: cy + Math.sin(a) * R,
      label: axis.label,
      lx: cx + Math.cos(a) * (R + 14),
      ly: cy + Math.sin(a) * (R + 14),
      anchor: Math.abs(Math.cos(a)) < 0.2 ? 'middle' : (Math.cos(a) > 0 ? 'start' : 'end'),
      baseline: Math.abs(Math.sin(a)) < 0.2 ? 'middle' : (Math.sin(a) > 0 ? 'hanging' : 'auto'),
      a,
      valuePct: axis.valuePct,
      tooltip: axis.tooltip,
    };
  });
  const valuePoints = axisLines.map((p) => {
    const ratio = Math.max(0, Math.min(1, (Number(p.valuePct) || 0) / cap));
    return { x: cx + Math.cos(p.a) * R * ratio, y: cy + Math.sin(p.a) * R * ratio };
  });
  return { cx, cy, rings, axisLines, valuePoints, cap };
}

export function getPassiveGrowthRows(game: GameRuntime): PassiveGrowthRow[] {
  const growthAnalysis = game.getPassiveGrowthAnalysis?.();
  if (!growthAnalysis || !Array.isArray(growthAnalysis.rows)) return [];
  return growthAnalysis.rows;
}
