<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- trainer rank badge */
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { stats } from '../../stores/stats.svelte.ts';
  import { buildRecordsTabData } from '../../stats/statsTabData.js';
  import StatsMetricRows from './StatsMetricRows.svelte';
  import StatsBiggestHit from './StatsBiggestHit.svelte';

  let data = $derived.by(() => {
    stats.contentRevision;
    const gm = game as GameRuntime | null;
    if (!gm) return null;
    return buildRecordsTabData(gm);
  });

  let t = $derived((key: string) => (game as GameRuntime | null)?.t?.(`statsUi.${key}`) ?? key);
</script>

{#if data}
  {#if data.sessionBanner}
    <StatsMetricRows title="" rows={[data.sessionBanner]} first />
  {/if}
  <div class="farming-metrics-section" style:margin-top={data.sessionBanner ? null : '0'} style:padding-top={data.sessionBanner ? null : '0'} style:border-top={data.sessionBanner ? null : 'none'}>
    <div class="farming-metrics-grid">
      <StatsBiggestHit />
    </div>
  </div>
  <StatsMetricRows title={t('sectionRecords')} rows={data.recordsMetrics} />
  {#if data.trainerScore}
    <StatsMetricRows title={t('sectionTrainerScore')} rows={[data.trainerScore]} />
  {/if}
{/if}
