<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { stats } from '../../stores/stats.svelte.ts';
  import { buildHeatmapCells, heatmapCellFill } from '../../lib/statsVisualData.js';

  const WEEKS = 12;
  const CELL_SIZE = 12;
  const GAP = 2;

  let gm = $derived(game as GameRuntime | null);
  let t = $derived((key: string) => gm?.t?.(`statsUi.${key}`) ?? key);

  let cells = $derived.by(() => {
    stats.contentRevision;
    if (!gm) return [];
    return buildHeatmapCells(gm, WEEKS);
  });

  let svgW = $derived(WEEKS * (CELL_SIZE + GAP));
  let svgH = $derived(7 * (CELL_SIZE + GAP));
  let hasActivity = $derived(cells.some((c) => c.score > 0));
</script>

<div class="farming-metrics-section">
  <div class="farming-metrics-section-title">{t('sectionHeatmap')}</div>
  <div class="farming-metrics-grid">
    {#if hasActivity}
      <div class="metric-row metric-row-wide" style="background:transparent;border:none;padding:6px 0">
        <div style="width:100%;overflow-x:auto">
          <svg viewBox="0 0 {svgW} {svgH}" class="stats-heatmap" aria-hidden="true">
            {#each cells as cell, idx (cell.key + idx)}
              {@const col = Math.floor(idx / 7)}
              {@const row = idx % 7}
              {@const x = col * (CELL_SIZE + GAP)}
              {@const y = row * (CELL_SIZE + GAP)}
              <rect
                x={x}
                y={y}
                width={CELL_SIZE}
                height={CELL_SIZE}
                rx="2"
                ry="2"
                fill={heatmapCellFill(cell.intensity)}
                stroke={cell.isToday ? '#fbbf24' : 'none'}
                stroke-width={cell.isToday ? 1 : 0}
              >
                <title>{cell.key} : {cell.score}</title>
              </rect>
            {/each}
          </svg>
        </div>
        <div class="metric-sub" style="width:100%">{t('heatmapHint')}</div>
      </div>
    {:else}
      <div class="metric-row metric-row-wide">
        <span class="metric-label">{t('heatmapEmpty')}</span>
      </div>
    {/if}
  </div>
</div>
