<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { stats } from '../../stores/stats.svelte.ts';
  import { buildStatsTimelineData, buildSparklinePoints } from '../../lib/statsVisualData.js';
  import { formatNumber } from '../../../formatters.ts';

  let gm = $derived(game as GameRuntime | null);
  let t = $derived((key: string) => gm?.t?.(`statsUi.${key}`) ?? key);

  let timeline = $derived.by(() => {
    stats.contentRevision;
    if (!gm) return { source: 'none' as const, items: [], emptyHintKey: 'timelineEmptyHint' };
    return buildStatsTimelineData(gm, (key) => t(key));
  });
</script>

<div class="farming-metrics-section">
  <div class="farming-metrics-section-title">{t('timelineTitle')}</div>
  <div class="farming-metrics-grid">
    {#if timeline.items.length > 0}
      {#each timeline.items as item (item.key)}
        <div class="metric-row metric-row-wide">
          <span class="metric-label">{item.label}</span>
          <span class="metric-value">{formatNumber(item.total)}</span>
          <div class="metric-sub" style="width:100%">
            <svg viewBox="0 0 220 32" preserveAspectRatio="none" class="stats-sparkline" aria-hidden="true">
              <polyline
                fill="none"
                stroke={item.color}
                stroke-width="1.5"
                points={buildSparklinePoints(item.values)}
              />
            </svg>
          </div>
        </div>
      {/each}
      {#if timeline.source === 'daily'}
        <div class="metric-row metric-row-wide" style="background:transparent;border:none;padding:0">
          <div class="metric-sub" style="width:100%">{t('timelineDailyHint')}</div>
        </div>
      {/if}
    {:else}
      <div class="metric-row metric-row-wide">
        <span class="metric-label">{t('timelineEmpty')}</span>
        <div class="metric-sub" style="width:100%">{t(timeline.emptyHintKey)}</div>
      </div>
    {/if}
  </div>
</div>
