<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { stats } from '../../stores/stats.svelte.ts';
  import { buildBiggestHitData } from '../../lib/statsVisualData.js';
  import { formatNumber } from '../../../formatters.ts';

  let gm = $derived(game as GameRuntime | null);
  let t = $derived((key: string) => gm?.t?.(`statsUi.${key}`) ?? key);

  let hit = $derived.by(() => {
    stats.contentRevision;
    if (!gm) return null;
    return buildBiggestHitData(gm, (key) => t(key));
  });
</script>

{#if hit}
  <div class="metric-row metric-row-highlight metric-row-wide">
    <span class="metric-label">{t('biggestSingleHit')}</span>
    <span class="metric-value">{formatNumber(hit.value)}</span>
    {#if hit.subtitle}
      <div class="metric-sub" class:metric-sub-shiny={hit.isShiny}>{hit.subtitle}</div>
    {/if}
  </div>
{/if}
