<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { stats } from '../../stores/stats.svelte.ts';
  import { buildCombatTabData } from '../../stats/statsTabData.js';
  import StatsMetricRows from './StatsMetricRows.svelte';
  import StatsCombatTopZones from './StatsCombatTopZones.svelte';
  import StatsRadar from './StatsRadar.svelte';

  let data = $derived.by(() => {
    stats.contentRevision;
    const gm = (game as GameRuntime | null)
      ?? (globalThis as { game?: GameRuntime }).game
      ?? null;
    if (!gm) return null;
    return buildCombatTabData(gm);
  });

  let sectionCombat = $derived((game as GameRuntime | null)?.t?.('statsUi.sectionCombat') ?? 'Combat');
  let sectionAdvanced = $derived((game as GameRuntime | null)?.t?.('statsUi.sectionAdvancedCombat') ?? 'Combat avancé');
  let sectionTopZones = $derived((game as GameRuntime | null)?.t?.('statsUi.sectionTopZones') ?? 'Top zones');
  let topZonesEmpty = $derived((game as GameRuntime | null)?.t?.('statsUi.topZonesEmpty') ?? '');
  let hasSessionBanner = $derived(!!data?.sessionBanner);
</script>

{#if data}
  {#if data.sessionBanner}
    <StatsMetricRows title="" rows={[data.sessionBanner]} first />
  {/if}
  <StatsRadar first={!hasSessionBanner} />
  <StatsMetricRows title={sectionCombat} rows={data.metrics} first={false} />
  <StatsMetricRows title={sectionAdvanced} rows={data.advancedMetrics} />
  <StatsCombatTopZones
    title={sectionTopZones}
    rows={data.topZones}
    emptyLabel={topZonesEmpty}
  />
{/if}
