<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { stats } from '../../stores/stats.svelte.ts';
  import {
    buildStatsRadarData,
    bonusRadarGeometry,
    type StatsRadarMode,
  } from '../../lib/statsVisualData.js';

  let { first = false }: { first?: boolean } = $props();

  let gm = $derived(game as GameRuntime | null);
  let t = $derived((key: string, vars: Record<string, unknown> = {}) =>
    gm?.t?.(`statsUi.${key}`, vars) ?? key,
  );

  let radarData = $derived.by(() => {
    stats.contentRevision;
    if (!gm) return null;
    return buildStatsRadarData(gm, (key, vars) => t(key, vars ?? {}));
  });

  let geo = $derived(radarData ? bonusRadarGeometry(radarData.axes, 100) : null);

  const MODES: { mode: StatsRadarMode; labelKey: string }[] = [
    { mode: 'team', labelKey: 'radarStatScopeTeam' },
    { mode: 'pension', labelKey: 'radarStatScopePension' },
    { mode: 'team_pension', labelKey: 'radarStatScopeTeamPension' },
    { mode: 'main', labelKey: 'radarStatScopeMain' },
  ];

  function selectMode(mode: StatsRadarMode) {
    const g = game as GameRuntime | null;
    if (g && typeof g.setStatsUi === 'function') {
      g.setStatsUi('radarMode', mode);
    }
  }

  function showAxisTooltip(e: MouseEvent, title: string) {
    const g = game as GameRuntime | null;
    g?.scheduleTooltip?.(e, title, '');
  }

  function hideTooltip() {
    (game as GameRuntime | null)?.hideTooltip?.();
  }
</script>

{#if radarData && geo}
  <div
    class="farming-metrics-section"
    style:margin-top={first ? '0' : null}
    style:padding-top={first ? '0' : null}
    style:border-top={first ? 'none' : null}
  >
    <div class="farming-metrics-section-title">{t('radarStatTitle')}</div>
    <div class="farming-metrics-grid">
      <div class="metric-row metric-row-wide" style="background:transparent;border:none;padding:6px 0">
        <div class="stats-radar-mode-row">
          <span class="stats-radar-mode-label">{t('radarStatScope')}</span>
          {#each MODES as chip (chip.mode)}
            <button
              type="button"
              class="stats-radar-mode-chip"
              class:active={radarData.mode === chip.mode}
              onclick={() => selectMode(chip.mode)}
            >
              {t(chip.labelKey)}
            </button>
          {/each}
        </div>
        <div class="stats-radar-svg-wrap">
          <svg viewBox="0 0 220 220" class="bonus-radar" aria-hidden="true">
            {#each geo.rings as ring, ri (ri)}
              <polygon
                points={ring.map((p) => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ')}
                fill="none"
                stroke="rgba(148,163,184,0.18)"
                stroke-width="1"
              />
            {/each}
            {#each geo.axisLines as axis, i (i)}
              <line
                x1={geo.cx}
                y1={geo.cy}
                x2={axis.x2.toFixed(1)}
                y2={axis.y2.toFixed(1)}
                stroke="rgba(148,163,184,0.18)"
                stroke-width="1"
              />
              <text
                x={axis.lx.toFixed(1)}
                y={axis.ly.toFixed(1)}
                text-anchor={axis.anchor}
                dominant-baseline={axis.baseline}
                fill="#cbd5e1"
                font-size="10"
              >{axis.label}</text>
            {/each}
            <polygon
              points={geo.valuePoints.map((p) => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ')}
              fill="rgba(96,165,250,0.35)"
              stroke="rgba(96,165,250,0.9)"
              stroke-width="1.5"
            />
            {#each geo.axisLines as axis, i (i)}
              {@const pt = geo.valuePoints[i]}
              {#if pt}
                <circle
                  cx={pt.x.toFixed(1)}
                  cy={pt.y.toFixed(1)}
                  r="3"
                  fill="rgba(96,165,250,0.95)"
                  onmouseenter={(e) => showAxisTooltip(e, axis.tooltip)}
                  onmouseleave={hideTooltip}
                />
              {/if}
            {/each}
          </svg>
        </div>
        <div class="metric-sub" style="width:100%">{t(radarData.hintKey)}</div>
      </div>
    </div>
  </div>
{/if}

<style>
  .stats-radar-mode-row {
    width: 100%;
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    align-items: center;
    justify-content: center;
    margin-bottom: 6px;
  }
  .stats-radar-mode-label {
    opacity: 0.75;
    font-size: 12px;
    margin-right: 4px;
  }
  .stats-radar-mode-chip {
    padding: 2px 10px;
    border-radius: 6px;
    font-size: 12px;
    cursor: pointer;
    background: rgba(148, 163, 184, 0.08);
    color: #cbd5e1;
    border: 1px solid transparent;
  }
  .stats-radar-mode-chip.active {
    background: rgba(96, 165, 250, 0.25);
    color: #dbeafe;
    border-color: rgba(96, 165, 250, 0.55);
  }
  .stats-radar-mode-chip:hover {
    background: rgba(96, 165, 250, 0.18);
  }
  .stats-radar-svg-wrap {
    width: 100%;
    display: flex;
    justify-content: center;
  }
</style>
