<script lang="ts">
  import type { StatsRankedRow } from '../../stats/statsTabData.js';

  let {
    title,
    rows,
    emptyLabel = '',
    first = false,
  }: {
    title: string;
    rows: StatsRankedRow[];
    emptyLabel?: string;
    first?: boolean;
  } = $props();
</script>

<div
  class="farming-metrics-section"
  style:margin-top={first ? '0' : null}
  style:padding-top={first ? '0' : null}
  style:border-top={first ? 'none' : null}
>
  <div class="farming-metrics-section-title">{title}</div>
  <div class="farming-metrics-grid">
    {#if rows.length === 0 && emptyLabel}
      <div class="metric-row metric-row-wide">
        <span class="metric-label">{emptyLabel}</span>
      </div>
    {:else}
      {#each rows as row (row.rank + row.label)}
        <div class="metric-row metric-row-wide farming-metrics-top-item">
          <span class="metric-label">
            {#if row.spriteUrl}
              <img
                class="farming-metrics-top-item-sprite"
                src={row.spriteUrl}
                alt=""
                onerror={(e) => { (e.currentTarget as HTMLImageElement).style.display = 'none'; }}
              />
            {/if}
            <span style="opacity:.6;margin-right:4px">#{row.rank}</span>
            {row.label}
          </span>
          <span class="metric-value">{row.value}</span>
          {#if row.sub}
            <div class="metric-sub" style="width:100%">{row.sub}</div>
          {/if}
        </div>
      {/each}
    {/if}
  </div>
</div>
