<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { stats } from '../../stores/stats.svelte.ts';
  import { buildGrowthTabData } from '../../stats/statsTabData.js';
  import StatsMetricRows from './StatsMetricRows.svelte';
  import StatsHeatmap from './StatsHeatmap.svelte';
  import StatsTimeline from './StatsTimeline.svelte';
  import StatsGrowthAnalysis from './StatsGrowthAnalysis.svelte';

  let data = $derived.by(() => {
    stats.contentRevision;
    const gm = game as GameRuntime | null;
    if (!gm) return null;
    return buildGrowthTabData(gm);
  });

  let t = $derived((key: string) => (game as GameRuntime | null)?.t?.(`statsUi.${key}`) ?? key);
</script>

{#if data}
  {#if data.sessionBanner}
    <StatsMetricRows title="" rows={[data.sessionBanner]} first />
  {/if}
  <StatsMetricRows title={t('sectionProgression')} rows={data.progressionMetrics} first={!data.sessionBanner} />
  <StatsMetricRows title={t('sectionWeeklyComparison')} rows={data.weeklyMetrics} />
  <StatsHeatmap />
  <StatsTimeline />
  <StatsGrowthAnalysis />
{/if}
